/* ===== Joystick (touch movement) + question bar ===== */
#joystick {
  position: absolute;
  bottom: 5%;
  left: 5%;
  width: 110px;
  height: 110px;
  z-index: 50;
  display: none;
}
.j-base {
  width: 100%;
  height: 100%;
