}
@keyframes boss-hit-flash {
    0%, 100% { filter: brightness(1) drop-shadow(0 0 18px rgba(157, 78, 221, 0.55)); }
    40% { filter: brightness(2.6) drop-shadow(0 0 32px rgba(255, 209, 102, 0.98)) hue-rotate(-20deg); }
